def run_batch(funcs):
    results = []
    errors = []
    for f in funcs:
        try:
            results.append(f())
        except Exception as e:
            errors.append(e)
    if errors:
        raise ExceptionGroup("batch failed", errors)
    return results

def ok():
    return 1

def bad_value():
    raise ValueError("v1")

def bad_key():
    raise KeyError("k1")

def bad_value2():
    raise ValueError("v2")

try:
    run_batch([ok, bad_value, bad_key, bad_value2])
except* ValueError as eg:
    print("ValueError:", len(eg.exceptions))
except* KeyError as eg:
    print("KeyError:", len(eg.exceptions))

def flatten(group):
    names = []
    for e in group.exceptions:
        if isinstance(e, BaseExceptionGroup):
            names.extend(flatten(e))
        else:
            names.append(type(e).__name__)
    return names

nested = ExceptionGroup("outer", [
    ValueError("a"),
    ExceptionGroup("inner", [KeyError("b"), TypeError("c")]),
])
print(flatten(nested))
